const req = $input.first().json || {};
const body = (req.body && typeof req.body === 'object') ? req.body : {};
const sessionId = (typeof body.sessionId === 'string' && body.sessionId.trim()) ? body.sessionId.trim().slice(0, 200) : null;
const original = body.chatInput;
function fail(msg) {
  return [{ json: { valid: false, sessionId: sessionId, response: {
    success: false, intent: 'entrada_invalida', message: msg, source: 'OECE/CONOSCE',
    total: 0, records: [], fallbackUsed: false, sessionId: sessionId
  } } }];
}
if (typeof original !== 'string' || original.trim().length === 0) return fail('El campo chatInput es obligatorio y debe ser un texto no vacio.');
const pregunta = original.replace(/\s+/g, ' ').trim();
if (pregunta.length > 1000) return fail('La pregunta excede el maximo de 1000 caracteres.');
return [{ json: { valid: true, pregunta: pregunta, sessionId: sessionId, startedAt: Date.now() } }];

const v = $('Validar entrada').first().json;
const out = ($input.first().json && $input.first().json.output) || {};
const ALLOWED = ['oece_adjudicacion', 'oece_ampliacion_contrato', 'oece_arbitraje', 'oece_consorcio', 'oece_consorcio_miembro',
  'oece_contrato', 'oece_convocatoria', 'oece_convocatoria_item', 'oece_evento_proceso', 'oece_miembro_comite',
  'oece_oferta_postor', 'oece_orden', 'oece_pac_item', 'oece_proveedor'];
const SKIP = ['lateral', 'only', 'select'];
const pideTodo = /\b(todo|toda|todos|todas)\b/i.test(v.pregunta);

function check(raw) {
  if (typeof raw !== 'string' || !raw.trim()) return { ok: false, reason: 'SQL vacio' };
  let sql = raw.trim().replace(/^```(sql)?/i, '').replace(/```$/, '').trim().replace(/;+\s*$/, '').trim();
  if (sql.length > 8000) return { ok: false, reason: 'SQL demasiado largo' };
  // Quitar literales e identificadores entre comillas antes de analizar
  let s = sql.replace(/'(?:[^']|'')*'/g, "''").replace(/"(?:[^"]|"")*"/g, 'qid').toLowerCase();
  if (s.indexOf(';') >= 0) return { ok: false, reason: 'Multiples sentencias' };
  if (/--|\/\*/.test(s)) return { ok: false, reason: 'Comentarios no permitidos' };
  if (/\$/.test(s)) return { ok: false, reason: 'Parametros o dollar-quoting no permitidos' };
  if (!/^\s*(select|with)\b/.test(s)) return { ok: false, reason: 'Solo se permite SELECT o WITH' };
  const kw = s.match(/\b(insert|update|delete|drop|alter|truncate|create|grant|revoke|copy|call|do|merge|execute|prepare|deallocate|vacuum|analyze|cluster|reindex|listen|notify|unlisten|set|reset|lock|comment|refresh|security|import|load|discard|checkpoint|into)\b/);
  if (kw) return { ok: false, reason: 'Palabra prohibida: ' + kw[1] };
  if (/\b(pg_[a-z_]*|dblink[a-z_]*|lo_[a-z_]+|current_setting|set_config|query_to_xml|txid_[a-z_]+)\s*\(/.test(s)) return { ok: false, reason: 'Funcion no permitida' };
  if (/\b(pg_catalog|information_schema|pg_[a-z_]+)\b/.test(s)) return { ok: false, reason: 'Catalogo del sistema no permitido' };
  const pref = s.match(/\b(app_|dim_|hecho_|rag_|ingesta_|log_|vw_)[a-z0-9_]*/);
  if (pref) return { ok: false, reason: 'Tabla no permitida: ' + pref[0] };
  s = s.replace(/\bpublic\./g, '');
  // Neutralizar FROM que no introduce tablas: EXTRACT(x FROM col), SUBSTRING/TRIM/OVERLAY(... FROM ...), IS DISTINCT FROM
  s = s.replace(/\bextract\s*\(\s*[a-z_]+\s+from\b/g, 'extract(')
    .replace(/\b(substring|trim|overlay)\s*\(([^()]*?)\bfrom\b/g, '$1($2,')
    .replace(/\bdistinct\s+from\b/g, 'distinct_op');
  const ctes = [];
  const reCte = /(?:\bwith\b|,)\s*(?:recursive\s+)?([a-z_][a-z0-9_]*)\s+as\s*\(/g;
  let m;
  while ((m = reCte.exec(s)) !== null) ctes.push(m[1]);
  const reTbl = /\b(?:from|join)\s+([a-z_][a-z0-9_.]*)(?!\s*\()/g;
  while ((m = reTbl.exec(s)) !== null) {
    const t = m[1];
    if (SKIP.indexOf(t) >= 0 || ctes.indexOf(t) >= 0) continue;
    if (ALLOWED.indexOf(t) < 0) return { ok: false, reason: 'Tabla no permitida: ' + t };
  }
  const oece = s.match(/\boece_[a-z0-9_]+/g) || [];
  for (const t of oece) if (ALLOWED.indexOf(t) < 0) return { ok: false, reason: 'Tabla no permitida: ' + t };
  if (/\bselect\s+(distinct\s+)?\*/.test(s) || /[a-z0-9_]\.\*/.test(s)) {
    if (!pideTodo) return { ok: false, reason: 'SELECT * no permitido' };
  }
  // Tope duro de 200 filas para cualquier consulta
  return { ok: true, sql: sql, final: 'SELECT * FROM (\n' + sql + '\n) AS consulta_oece LIMIT 200' };
}

const base = { pregunta: v.pregunta, sessionId: v.sessionId, startedAt: v.startedAt,
  accion: out.accion === 'aclarar' ? 'aclarar' : 'sql',
  columnas: Array.isArray(out.columnas_salida) ? out.columnas_salida : [],
  explicacion: typeof out.explicacion === 'string' ? out.explicacion : '',
  mensaje: typeof out.mensaje === 'string' ? out.mensaje : '',
  records: [], total: 0, fallbackUsed: false, logTecnico: null };

if (base.accion === 'aclarar') {
  return [{ json: Object.assign(base, { estado: 'aclarar', mensaje: base.mensaje || 'Por favor precise su consulta (entidad, RUC, codigo de convocatoria o periodo).' }) }];
}
const p = check(out.sql);
if (!p.ok) {
  return [{ json: Object.assign(base, { estado: 'rechazado', logTecnico: 'Guardia SQL rechazo la consulta principal: ' + p.reason }) }];
}
// Respaldo ampliado: debe conservar anio, RUC y codigos (literales numericos de 4+ digitos)
let sqlAmpliada = '';
const a = check(out.sql_ampliada);
if (a.ok && a.sql !== p.sql) {
  const nums = p.sql.match(/\d{4,}/g) || [];
  const conserva = nums.every(function (n) { return a.sql.indexOf(n) >= 0; });
  if (conserva) sqlAmpliada = a.final;
}
let sqlAlternativa = '';
const b = check(out.sql_alternativa);
if (b.ok && b.sql !== p.sql) sqlAlternativa = b.final;
return [{ json: Object.assign(base, { estado: 'listo', sql: p.final, sqlAmpliada: sqlAmpliada, sqlAlternativa: sqlAlternativa }) }];

function leer(items) {
  const err = items.find(function (i) { return i.json && i.json.error; });
  if (err) return { error: String(err.json.message || (err.json.error && (err.json.error.message || err.json.error.description)) || 'error desconocido').slice(0, 500), rows: [] };
  const rows = items.map(function (i) { return i.json || {}; }).filter(function (j) {
    const k = Object.keys(j);
    if (k.length === 0) return false;
    if (k.length === 1 && j.success === true) return false;
    return true;
  });
  return { error: null, rows: rows };
}
const ctx = $('Validar SQL (guardia)').first().json;
const r = leer($input.all());
const outp = Object.assign({}, ctx, { records: r.rows, total: r.rows.length, needFallback: false, fallbackSql: '', fallbackTipo: null });
if (r.error) {
  outp.estado = 'error';
  outp.logTecnico = 'Error en SQL principal tras reintentos: ' + r.error;
  if (ctx.sqlAlternativa) { outp.needFallback = true; outp.fallbackSql = ctx.sqlAlternativa; outp.fallbackTipo = 'alternativa'; }
} else if (r.rows.length === 0) {
  outp.estado = 'vacio';
  if (ctx.sqlAmpliada) { outp.needFallback = true; outp.fallbackSql = ctx.sqlAmpliada; outp.fallbackTipo = 'ampliada'; }
} else {
  outp.estado = 'ok';
}
return [{ json: outp }];

function leer(items) {
  const err = items.find(function (i) { return i.json && i.json.error; });
  if (err) return { error: String(err.json.message || (err.json.error && (err.json.error.message || err.json.error.description)) || 'error desconocido').slice(0, 500), rows: [] };
  const rows = items.map(function (i) { return i.json || {}; }).filter(function (j) {
    const k = Object.keys(j);
    if (k.length === 0) return false;
    if (k.length === 1 && j.success === true) return false;
    return true;
  });
  return { error: null, rows: rows };
}
const ctx = $('Evaluar resultado principal').first().json;
const r = leer($input.all());
const outp = Object.assign({}, ctx, { records: r.rows, total: r.rows.length, fallbackUsed: true, needFallback: false });
if (r.error) {
  outp.estado = 'error';
  outp.logTecnico = (ctx.logTecnico ? ctx.logTecnico + ' | ' : '') + 'Error en SQL de respaldo (' + ctx.fallbackTipo + '): ' + r.error;
} else {
  outp.estado = r.rows.length ? 'ok' : 'vacio';
}
return [{ json: outp }];

const d = $input.first().json || {};
if (d.logTecnico) console.error('[OECE SQL] exec ' + $execution.id + ': ' + d.logTecnico);
const res = { success: true, intent: d.accion || 'sql', message: '', source: 'OECE/CONOSCE', total: 0, records: [],
  fallbackUsed: !!d.fallbackUsed, columns: d.columnas || [], explanation: d.explicacion || '', sessionId: d.sessionId || null };
if (d.estado === 'aclarar') {
  res.intent = 'aclarar';
  res.message = d.mensaje;
} else if (d.estado === 'rechazado') {
  res.success = false;
  res.intent = 'rechazado';
  res.message = 'No se pudo generar una consulta segura para esta pregunta. Reformulela indicando entidad, RUC, codigo de convocatoria o periodo.';
} else if (d.estado === 'error') {
  res.success = false;
  res.message = 'No fue posible consultar la base de datos en este momento. Intente nuevamente mas tarde.';
} else {
  const recs = Array.isArray(d.records) ? d.records : [];
  res.records = recs;
  res.total = recs.length;
  if (recs.length === 0) {
    res.message = 'No se encontraron registros en los datos OECE/CONOSCE cargados para esta consulta.';
    if (d.fallbackUsed) res.message += ' Tambien se probo una busqueda ampliada sin resultados.';
  } else {
    res.message = 'Se encontraron ' + recs.length + ' registro(s) en los datos OECE/CONOSCE.';
    if (recs.length >= 200) res.message += ' Resultado limitado a 200 filas.';
    if (d.fallbackUsed) res.message += d.fallbackTipo === 'ampliada' ? ' Se amplio la busqueda textual porque la consulta exacta no devolvio resultados.' : ' Se uso una consulta alternativa simplificada.';
  }
}
return [{ json: res }];
